import { pool } from "../config/db.js";

export async function listFees(req, res, next) {
  try {
    const classId = req.query.class_id ? Number(req.query.class_id) : null;
    const section = req.query.section ? String(req.query.section) : null;

    if (req.user.role === "student") {
      const result = await pool.query(
        `select f.*
         from fees f
         join students s on s.id = f.student_id
         where s.user_id = $1
         order by f.due_date desc, f.id desc`,
        [req.user.id],
      );
      return res.json({ fees: result.rows });
    }

    const where = [];
    const values = [];
    if (classId) {
      values.push(classId);
      where.push(`f.class_id = $${values.length}`);
    }
    if (section) {
      values.push(section);
      where.push(`c.section = $${values.length}`);
    }

    const result = await pool.query(
      `select
        f.*,
        u.name as student_name,
        c.class_name,
        c.section
      from fees f
      join students s on s.id = f.student_id
      join users u on u.id = s.user_id
      join classes c on c.id = f.class_id
      ${where.length ? `where ${where.join(" and ")}` : ""}
      order by f.due_date desc, f.id desc`,
      values,
    );
    return res.json({ fees: result.rows });
  } catch (e) {
    return next(e);
  }
}

export async function addFee(req, res, next) {
  try {
    const { student_id, class_id, amount, due_date } = req.validated.body;

    const student = await pool.query("select id, class_id from students where id = $1", [
      student_id,
    ]);
    if (student.rowCount === 0) return res.status(400).json({ error: "student_id not found" });
    if (Number(student.rows[0].class_id) !== Number(class_id))
      return res.status(400).json({ error: "student_id not in selected class" });

    const created = await pool.query(
      `insert into fees (student_id, class_id, amount, due_date, status)
       values ($1, $2, $3, $4, 'pending')
       returning *`,
      [student_id, class_id, amount, due_date],
    );
    return res.status(201).json({ fee: created.rows[0] });
  } catch (e) {
    return next(e);
  }
}

export async function payFee(req, res, next) {
  try {
    const id = req.validated.params.id;
    const updated = await pool.query(
      `update fees
       set status = 'paid', paid_on = now()
       where id = $1
       returning *`,
      [id],
    );
    if (updated.rowCount === 0) return res.status(404).json({ error: "Fee not found" });
    return res.json({ fee: updated.rows[0] });
  } catch (e) {
    return next(e);
  }
}

